def _topological_order(root):
    """Return all cells reachable from root, dependencies before dependents."""
    visited = set()
    order = []

    def visit(cell):
        if id(cell) in visited:
            return
        visited.add(id(cell))
        for dependent in cell._dependents:
            visit(dependent)
        order.append(cell)

    visit(root)
    return order


